#!/usr/bin/env python
"""Collectors: read the runs (results/runs, $OPSIS_DATA/runs) and the organiser episodes (results/organiser) and write the result
tables to results/collected/ and the organiser summaries to results/organiser/. One subcommand per table:
    python scripts/collect/collect.py <subcommand> [options]      (python scripts/collect/collect.py <subcommand> -h for its options)
  baselines        field level baselines next to Opsis (CLAM-SB, PRISM2, CellViT++, zero shot vision language models)
  router           routing between Opsis-S and Opsis-V on their saved test predictions
  final            the final runs: mean and sd over seeds per operator
  ablations        the field decoder ablations against final_fov (same seed)
  selective        calibration and selective prediction from the saved test predictions
  organiser        accuracy, tool calls, tokens and cost of organiser conditions (--runs a,b,c)
  pan_comparables  the pan cancer slide comparison: Opsis-S, per tile heads, CLAM-SB, ABMIL, TITAN and PRISM2 probes
  organiser_set    every comparable on the organiser question set (30 TCGA-BRCA test slides)
  pan_organiser    the organiser on the whole pan cancer test split
  eyes             vision language models looking at slides and fields
  rules_composites Opsis-S with fixed rules on the composite operators
  ways_to_read     reading a description, looking at the slide and asking Opsis-S, per model
pan_organiser reads the table of pan_comparables, ways_to_read the majority class written by organiser_set.
"""
import argparse, collections, glob, json, os, pickle, re, sys

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "src"))
from opsis import paths


def baselines():
    """External baselines next to Opsis: CLAM-SB (scripts/baselines/57_clam_baseline.py), PRISM2 zero shot / mismatch /
linear probe (scripts/baselines/58_prism2_zeroshot.py), CellViT++ NuCLS heads (scripts/baselines/59_cellvit_nucls_dataset.py), against the slide decoder on the v2 questions (runs jev_v2_op_s0..2) and
on the v1 questions (runs slide_jev_s0..2) on the same test slides.
    python scripts/collect/collect.py baselines [--out results/collected/RESULTS_baselines_tables.md]"""
    import argparse, glob, json, os
    import numpy as np

    ap = argparse.ArgumentParser(); ap.add_argument("--out", default=f"{paths.ROOT}/results/collected/RESULTS_baselines_tables.md"); a = ap.parse_args(); R = paths.RUNS
    def load(name):
        f = f"{R}/{name}/metrics_test.json"; return json.load(open(f)) if os.path.exists(f) else None
    def agg(names, op, key):
        v = [m["per_op"][op][key] for n in names if (m := load(n)) and op in m["per_op"] and m["per_op"][op].get(key) is not None]
        return (float(np.mean(v)), float(np.std(v)), len(v)) if v else None
    def fmt(t, d=3): return "" if t is None else (f"{t[0]:.{d}f}" if t[2] == 1 else f"{t[0]:.{d}f} ± {t[1]:.{d}f}")
    TASKS = ["er_positive", "pr_positive", "her2_positive", "pam50", "histologic_grade", "histologic_type", "in_situ_present", "lvi_present", "necrosis_present", "multifocal", "lcis_present", "calcifications",
             "dcis_comedo_necrosis", "nuclear_grade", "tubule_score", "pleomorphism_score", "mitotic_score", "dcis_grade"]
    cols = {"Opsis-S breast v1 (3 seeds)": ["slide_jev_s0", "slide_jev_s1", "slide_jev_s2"], "Opsis-S breast (3 seeds)": ["jev_v2_op_s0", "jev_v2_op_s1", "jev_v2_op_s2"], "Opsis-S breast text+op": ["jev_v2_text_s0"],
            "CLAM-SB (seeds)": None, "ABMIL (seeds)": None, "TITAN probe": ["titan_brca_probe"], "PRISM2 probe": ["prism2_brca_probe"], "TITAN zero shot": ["titan_brca_zeroshot"], "PRISM2 zero shot": ["prism2_zeroshot"], "PRISM2 mismatched slide": ["prism2_zeroshot_mismatch"]}
    lines = ["# External baselines on our test slides (generated by scripts/collect/collect.py baselines)", "", "Accuracy (majority) with AUROC where defined; test split of the patient level split seed 0 (170 slides). CLAM-SB: repository defaults, full tile bags of the Virchow2 cache. ABMIL: the gated attention MIL of Ilse et al. 2018 (CLAM-SB's network without the instance clustering loss, scripts/baselines/57_clam_baseline.py --model abmil), full bags. PRISM2: Virchow2 class tokens sliced from the 256 px cache (the model expects 224 px), yes/no scoring for binary operators, multiple choice generation otherwise (accuracy only). Probes (scripts/baselines/88_fm_probes_brca.py): logistic regression on the released TITAN slide embeddings and on the PRISM2 base embeddings, every field, C chosen on val. TITAN zero shot: text prompts per field (scripts/baselines/88_fm_probes_brca.py).", ""]
    hdr = "| operator | maj | " + " | ".join(cols) + " |"; lines += [hdr, "|" + "---|" * (hdr.count("|") - 1)]
    for op in TASKS:
        cells = []; maj = None
        for g, names in cols.items():
            if g in ("CLAM-SB (seeds)", "ABMIL (seeds)"): names = sorted({os.path.basename(p) for p in glob.glob(f"{R}/{'clam' if g.startswith('CLAM') else 'abmil'}_{op}_s*") if "smoke" not in p})
            key_op = op
            acc, au = agg(names, key_op, "acc"), agg(names, key_op, "auroc")
            for n in names:
                m = load(n)
                if m and key_op in m["per_op"] and maj is None: maj = m["per_op"][key_op]["majority_acc"]
            cells.append("" if acc is None else (fmt(acc) + (f" / AUROC {fmt(au)}" if au else "")))
        if any(cells): lines.append(f"| {op} | {'' if maj is None else f'{maj:.2f}'} | " + " | ".join(cells) + " |")
    # CellViT++ NuCLS heads (classification on ground truth cells, and the detection + classification pipeline)
    rows = []
    for d in sorted(glob.glob(f"{R}/cellvit_nucls/*/*/test_results/inference_results.json")):
        b = d.split("/")[-4]; j = json.load(open(d)); g = j["classifier"]["global"]; ct = j["pipeline"]["detection_scores_tia"]["cell_types"]; det = j["pipeline"]["detection_scores_tia"]["binary"]
        rows.append(f"| CellViT++ {b} | {g['Acc']:.3f} | {g['F1']:.3f} | {g.get('Auroc', float('nan')):.3f} | {det['f1']:.3f} | " + " / ".join(f"{ct[k]['f1']:.2f}" for k in ("tumor_any", "nonTIL_stromal", "sTIL", "other_nucleus") if k in ct) + " |")
    if rows:
        lines += ["", "## NuCLS super classes on our test patients: CellViT++ heads vs Opsis-S", "", "| model | acc on GT cells | F1 | AUROC | detection F1 | pipeline F1 tumor / stromal / sTIL / other |", "|---|---|---|---|---|---|"] + rows
        ours = load("jevpool_dens_v2_s0") or load("jevpool_all_v2_s0")
        if ours and "cell_super" in ours["per_op"]: lines.append(f"| Opsis-S (oracle locations, {'density aux' if load('jevpool_dens_v2_s0') else 'jevpool'}) | {ours['per_op']['cell_super']['acc']:.3f} | {ours['per_op']['cell_super']['macro_f1']:.3f} | | | |")
    # CellViT++ heads on the seven NuCLS main classes (scripts/baselines/59_cellvit_nucls_dataset.py with LEVEL=main), the comparable of the cell class question
    MAIN7 = ("tumor_nonMitotic", "tumor_mitotic", "nonTILnonMQ_stromal", "macrophage", "lymphocyte", "plasma_cell", "other_nucleus"); rows = []
    for d in sorted(glob.glob(f"{R}/cellvit_nucls_main/*/*/test_results/inference_results.json")):
        b = d.split("/")[-4]; j = json.load(open(d)); g = j["classifier"]["global"]; ct = j["pipeline"]["detection_scores_tia"]["cell_types"]; det = j["pipeline"]["detection_scores_tia"]["binary"]
        rows.append(f"| CellViT++ {b} | {g['Acc']:.3f} | {g['F1']:.3f} | {g.get('Auroc', float('nan')):.3f} | {det['f1']:.3f} | " + " / ".join(f"{ct[k]['f1']:.2f}" for k in MAIN7 if k in ct) + " |")
    if rows:
        lines += ["", "## NuCLS main classes on our test patients: CellViT++ heads", "", "| model | acc on GT cells | F1 | AUROC | detection F1 | pipeline F1 " + " / ".join(MAIN7) + " |", "|---|---|---|---|---|---|"] + rows
    # blank image control on the final field question set (scripts/opsis_v/40_train_vlm.py --qset questions_final --blank-image): the same typed questions with a blank canvas
    BF = {"Qwen3-VL-8B": ("zs_qwen3vl8b_final", "zs_qwen3vl8b_blank_final"), "Patho-R1-7B": ("zs_pathor1_7b_final", "zs_pathor1_7b_blank_final")}; rows = []
    for name, (ri, rb) in BF.items():
        im, bl = load(ri), load(rb)
        if not (im and bl): continue      # the control of this model has not finished
        tot = lambda r: sum(v["acc"] * v["n"] for v in r["per_op"].values()) / sum(v["n"] for v in r["per_op"].values()); n = sum(v["n"] for v in im["per_op"].values())
        assert n == sum(v["n"] for v in bl["per_op"].values()), (name, "the two runs answered different questions")
        rows.append(f"| {name} | all questions | {n} | {tot(im):.3f} | {tot(bl):.3f} | {tot(im) - tot(bl):+.3f} |")
        for op in ("cell_super", "cell_main", "cell_area_bin", "compare_regions", "dominant_tissue", "stil_score_bin"):
            x, y = im["per_op"][op], bl["per_op"][op]; rows.append(f"| {name} | {op} | {x['n']} | {x['acc']:.3f} | {y['acc']:.3f} | {x['acc'] - y['acc']:+.3f} |")
    if rows: lines += ["", "## Blank image control on the final field question set", "", "| model | operator | n | with the canvases | blank image | difference |", "|---|---|---|---|---|---|"] + rows
    # zero shot VLMs on the FOV questions (scripts/opsis_v/40_train_vlm.py), with the blank image control as the language prior
    ZS = {"Opsis-S (jevpool_dens_v2_s0)": "jevpool_dens_v2_s0", "Opsis-V (vlm_all_v2_s0)": "vlm_all_v2_s0", "Qwen3-VL-8B zero shot": "zs_qwen3vl8b", "Qwen3-VL-8B zero shot, blank image": "zs_qwen3vl8b_blank", "Patho-R1-7B zero shot": "zs_pathor1_7b", "Patho-R1-7B zero shot, blank image": "zs_pathor1_7b_blank"}
    M = {k: load(v) for k, v in ZS.items() if load(v)}
    if M:
        ops = ["cell_super", "cell_main", "cell_area_bin", "cell_tissue", "count_bin", "present", "cell_frac_bin", "more_cells", "tissue_frac_bin", "dominant_tissue", "compare_regions", "count_in_compartment_bin", "tils_location"]
        lines += ["", "## Zero shot VLMs on the FOV questions (NuCLS v2 test, accuracy / NLL; the blank image rows are the language prior)", "", "| operator | maj | " + " | ".join(M) + " |", "|" + "---|" * (len(M) + 2)]
        for op in ops:
            cells = []; maj = None
            for m in M.values():
                r = m["per_op"].get(op)
                if r is None: cells.append(""); continue
                maj = maj or r["majority_acc"]; cells.append(f"{r['acc']:.3f} / {r['nll']:.2f}")
            lines.append(f"| {op} | {'' if maj is None else f'{maj:.2f}'} | " + " | ".join(cells) + " |")
        lines.append("| test NLL (all) | | " + " | ".join(f"{m['test_nll']:.3f}" for m in M.values()) + " |")
        lines += ["", "PRISM2 mismatched slide control (each slide replaced by another slide of the test set, probe of arXiv 2610.26805): ER 0.605 (AUROC 0.50) against 0.778 (AUROC 0.81) with the right slide, grade 0.331 against 0.697, LVI 0.600 against 0.727. PRISM2 zero shot therefore reads the slide; the published SlideChat probe (74.8 with the slide, 74.4 without) does not transfer to it."]
    txt = "\n".join(lines); print(txt)
    if a.out: open(a.out, "w").write(txt + "\n")



def router():
    """Routing between Opsis-S and Opsis-V (one question interface, two instantiations): evaluated offline on the predictions both
made on the same questions. Rules: per operator (chosen on val), confidence escalation (Opsis-S first, Opsis-V when the
Opsis-S max probability is below a val quantile), their combination, a learned router (logistic regression on
operator one hot + Opsis-S confidence + entropy, trained on val), and the oracle upper bound.
    python scripts/collect/collect.py router [--structured final_fov_s0+final_fov_s1+final_fov_s2] [--vlm final_vlm_s0+final_vlm_s1+final_vlm_s2]
        (run lists pair up by position: every rule is evaluated per seed pair, the table reports mean and sd over pairs)
Cost model (defaults of --cost-structured and --cost-vlm, ms per question, H200): Opsis-S = adapter + branches shared over 32 questions
(2.8 ms per state) plus the frozen encoder amortised over the questions of a state (measured 41.7 ms per state over 139 questions),
Opsis-V = shared prefix at 32 questions per state (8.1 ms per question, scripts/opsis_v/41_vlm_shared_prefix.py)."""
    import argparse, json
    import numpy as np, pandas as pd
    from sklearn.linear_model import LogisticRegression
    ap = argparse.ArgumentParser(); ap.add_argument("--structured", default="final_fov_s0+final_fov_s1+final_fov_s2"); ap.add_argument("--vlm", default="final_vlm_s0+final_vlm_s1+final_vlm_s2"); ap.add_argument("--out", default=f"{paths.ROOT}/results/collected/RESULTS_router_final.md")
    ap.add_argument("--cost-structured", type=float, default=2.8 / 32 + 41.7 / 139); ap.add_argument("--cost-vlm", type=float, default=8.1); a = ap.parse_args()
    LIST = lambda v: [x for x in v.replace("+", ",").split(",") if x]
    PAIRS = list(zip(LIST(a.structured), LIST(a.vlm))); assert PAIRS and len(LIST(a.structured)) == len(LIST(a.vlm)), "the two run lists must pair up by position"

    def load(run, split):
        P = pd.read_parquet(f"{paths.RUNS}/{run}/predictions_{split}.parquet"); P["probs"] = P["probs"].map(lambda p: np.asarray(p, dtype=float)); return P[["qid", "op", "family", "answer", "probs"]]
    def merge(structured, vlm, split):
        S = load(structured, split).rename(columns={"probs": "ps"}); V = load(vlm, split)[["qid", "probs"]].rename(columns={"probs": "pv"}); M = S.merge(V, on="qid")
        for c in ("ps", "pv"): M[c] = M[c].map(lambda p: p / p.sum())
        M["cs"] = M.apply(lambda r: int(np.argmax(r.ps)) == r.answer, axis=1); M["cv"] = M.apply(lambda r: int(np.argmax(r.pv)) == r.answer, axis=1)
        M["conf_s"] = M["ps"].map(np.max); M["ent_s"] = M["ps"].map(lambda p: -(p * np.log(p + 1e-9)).sum())
        M["nll_s"] = M.apply(lambda r: -np.log(max(r.ps[r.answer], 1e-6)), axis=1); M["nll_v"] = M.apply(lambda r: -np.log(max(r.pv[r.answer], 1e-6)), axis=1); return M

    def evaluate_pair(structured, vlm):
        val, test = merge(structured, vlm, "val"), merge(structured, vlm, "test"); rows = []
        def report(name, use_v, M=test):
            use_v = np.asarray(use_v, bool); acc = np.where(use_v, M.cv, M.cs).mean(); nll = np.where(use_v, M.nll_v, M.nll_s).mean(); f = use_v.mean(); cost = (1 - f) * a.cost_structured + f * a.cost_vlm
            rows.append(dict(rule=name, acc=acc, nll=nll, vlm_share=f, ms_per_question=cost)); print(f"{name:52s} acc {acc:.3f} NLL {nll:.3f} VLM {f:5.1%} {cost:5.2f} ms/q")
        n = len(test); report("structured only", np.zeros(n, bool)); report("VLM only", np.ones(n, bool)); report("oracle", (~test.cs & test.cv).to_numpy())
        better_v = {op: g.cv.mean() > g.cs.mean() for op, g in val.groupby("op")}; route_op = test.op.map(better_v).fillna(False).to_numpy(); report("per operator (chosen on val)", route_op); print("   operators routed to the VLM:", sorted(o for o, b in better_v.items() if b))
        for b in (0.1, 0.25, 0.5):
            tau = np.quantile(val.conf_s, b); report(f"confidence escalation, {b:.0%} of val", (test.conf_s < tau).to_numpy())
        for b in (0.1, 0.25):
            rest = val[~val.op.map(better_v).fillna(False)]; tau = np.quantile(rest.conf_s, b); report(f"per operator + confidence ({b:.0%} of the rest)", route_op | (test.conf_s < tau).to_numpy())
        ops = sorted(val.op.unique())
        def feats(M): X = pd.get_dummies(M.op).reindex(columns=ops, fill_value=0).astype(float); X["conf"] = M.conf_s.values; X["ent"] = M.ent_s.values; return X.values
        clf = LogisticRegression(C=1.0, max_iter=2000, class_weight="balanced").fit(feats(val), (~val.cs & val.cv).astype(int).values); pv = clf.predict_proba(feats(val))[:, 1]; pt = clf.predict_proba(feats(test))[:, 1]
        for b in (0.1, 0.25): report(f"learned router, {b:.0%} escalated", pt >= np.quantile(pv, 1 - b))
        # both instantiations on every question: probability fusion (no routing, costs both)
        def fused(M, w):
            ps = np.stack([np.pad(p, (0, 32 - len(p))) for p in M.ps]); pv = np.stack([np.pad(p, (0, 32 - len(p))) for p in M.pv]); return w * ps + (1 - w) * pv
        def geo(M):
            ps = np.stack([np.pad(p, (0, 32 - len(p))) for p in M.ps]); pv = np.stack([np.pad(p, (0, 32 - len(p))) for p in M.pv]); g = np.sqrt(ps * pv); return g / g.sum(1, keepdims=True)
        y = test.answer.to_numpy(); yv = val.answer.to_numpy()
        for name, P in (("fusion: arithmetic mean of both tiers", fused(test, 0.5)), ("fusion: geometric mean of both tiers", geo(test))):
            acc = (P.argmax(1) == y).mean(); nll = -np.log(np.clip(P[np.arange(len(y)), y], 1e-6, 1)).mean()
            rows.append(dict(rule=name, acc=acc, nll=nll, vlm_share=1.0, ms_per_question=a.cost_structured + a.cost_vlm)); print(f"{name:52s} acc {acc:.3f} NLL {nll:.3f} VLM 100.0% {a.cost_structured + a.cost_vlm:5.2f} ms/q")
        return pd.DataFrame(rows).assign(pair=f"{structured} vs {vlm}")

    D = pd.concat([(print(f"\n=== {s} vs {v}") or evaluate_pair(s, v)) for s, v in PAIRS], ignore_index=True); G = D.groupby("rule", sort=False)
    df = pd.DataFrame({"rule": list(G.groups), "acc": G.acc.mean().values, "acc_sd": G.acc.std(ddof=1).fillna(0).values, "nll": G.nll.mean().values, "nll_sd": G.nll.std(ddof=1).fillna(0).values, "vlm_share": G.vlm_share.mean().values, "ms_per_question": G.ms_per_question.mean().values})
    if len(PAIRS) > 1: print(f"\n=== mean over {len(PAIRS)} seed pairs"); print(df.round(3).to_string(index=False))
    if a.out:
        sd = len(PAIRS) > 1
        lines = [f"| {r.rule} | {r.acc:.3f}" + (f" ± {r.acc_sd:.3f}" if sd else "") + f" | {r.nll:.3f}" + (f" ± {r.nll_sd:.3f}" if sd else "") + f" | {r.vlm_share:.1%} | {r.ms_per_question:.2f} |" for r in df.itertuples()]
        open(a.out, "w").write("# Routing between Opsis-S and Opsis-V (generated by scripts/collect/collect.py router)\n\nPairs: " + ", ".join(f"{s} vs {v}" for s, v in PAIRS) + (" (mean ± sd over seed pairs)" if sd else "") + "\n\n| rule | acc | NLL | VLM share | ms per question |\n|---|---|---|---|---|\n" + "\n".join(lines) + "\n")



def final():
    """Collect the final runs into results/collected/RESULTS_final.md: mean and sd over seeds per operator for the field
decoder of Opsis-S (final_fov_s*, joint NuCLS + PanNuke), its PanNuke fold / held out organ evaluation, Opsis-V (final_vlm_s*),
the pan TCGA slide decoder (final_slide_pan_s*, test and held out projects) and the full bag tile heads (final_tile_*).
Runs that have not finished are skipped, so the script can be rerun as results land.
    python scripts/collect/collect.py final"""
    import glob, json, os, re
    import numpy as np, pandas as pd
    R = paths.RUNS
    def load(pattern):
        out = {}
        for d in sorted(glob.glob(f"{R}/{pattern}")):
            f = f"{d}/metrics_test.json"
            if os.path.exists(f): out[os.path.basename(d)] = json.load(open(f))
        return out
    def ms(v, nd=3):
        v = [x for x in v if x is not None]
        return "" if not v else (f"{np.mean(v):.{nd}f}" if len(v) == 1 else f"{np.mean(v):.{nd}f} ± {np.std(v, ddof=1):.{nd}f}")
    def table(runs, key, cols=("acc", "nll"), extra=None, ref=None):
        ops = sorted({op for m in runs.values() for op in m.get(key, {})}); rows = []
        for op in ops:
            r = {"operator": op, "n": next((m[key][op]["n"] for m in runs.values() if op in m.get(key, {})), ""), "maj": f"{next((m[key][op]['majority_acc'] for m in runs.values() if op in m.get(key, {})), 0):.2f}"}
            for c in cols: r[c] = ms([m[key][op].get(c) for m in runs.values() if op in m.get(key, {})])
            if extra:
                for name, rr in extra.items(): r[name] = ms([x[key][op].get(cols[0]) for x in rr.values() if op in x.get(key, {})])
            if ref:
                for name, rm in ref.items(): r[name] = f"{rm[key][op][cols[0]]:.3f}" if op in rm.get(key, {}) else ""
            rows.append(r)
        T = pd.DataFrame(rows)
        return ["| " + " | ".join(T.columns) + " |", "|" + "---|" * len(T.columns), *("| " + " | ".join(str(x) for x in r) + " |" for r in T.itertuples(index=False))] if len(T) else ["(no finished run)"]
    md = ["# Final results, collected by scripts/collect/collect.py final", ""]
    fov = load("final_fov_s[0-9]"); org = load("final_fov_organ_s[0-9]"); v2 = load("jevpool_dens_v2_s0"); vlm2 = load("vlm_all_v2_s0")
    md += [f"## Opsis-S on fields, joint NuCLS + PanNuke training ({len(fov)} seeds: {', '.join(fov)})", "",
           f"NuCLS v2 test, mean ± sd over seeds. Overall test NLL {ms([m['test_nll'] for m in fov.values()])} (earlier single seed jevpool_dens_v2_s0: {ms([m['test_nll'] for m in v2.values()])}, Opsis-V vlm_all_v2_s0: {ms([m['test_nll'] for m in vlm2.values()])}).", ""]
    md += table(fov, "per_op", ("acc", "nll", "ece"), ref={"r5 structured acc": next(iter(v2.values()), {}), "r5 VLM acc": next(iter(vlm2.values()), {})} if v2 and vlm2 else None)
    md += ["", f"PanNuke test (fold split, {len(fov)} seeds) and held out organs (final_fov_organ_s*, {len(org)} seed): accuracy.", ""]
    md += table(fov, "per_op_extra", ("acc", "nll"), extra={"held out organs acc": org} if org else None)
    tuned = load("final_fov_tuned_s[0-9]"); ctl = load("final_fov_tunedctl_s[0-9]")
    if tuned:
        md += ["", f"## Tuned state: Virchow2 last 4 blocks unfrozen, readout initialised from final_fov_s0 ({len(tuned)} seed); control = same continued training with the encoder frozen ({len(ctl)} seed)", "",
               f"NuCLS test NLL: tuned {ms([m['test_nll'] for m in tuned.values()])}, control {ms([m['test_nll'] for m in ctl.values()])}, frozen reference final_fov_s0 {ms([m['test_nll'] for m in load('final_fov_s0').values()])}. Validation NLL did not improve over the initial readout in either run (train NLL kept falling), so the encoder is not the lever at this data scale.", ""]
        md += table(tuned, "per_op", ("acc", "nll"), extra={"control acc": ctl, "frozen final_fov_s0 acc": load("final_fov_s0")})
        md += ["", "PanNuke test:", ""] + table(tuned, "per_op_extra", ("acc", "nll"), extra={"control acc": ctl, "frozen final_fov_s0 acc": load("final_fov_s0")})
    vlm = load("final_vlm_s[0-9]")
    md += ["", f"## Opsis-V, Qwen3-VL-8B LoRA on questions_final ({len(vlm)} seeds)", "", f"Test NLL {ms([m['test_nll'] for m in vlm.values()])}.", ""] + table(vlm, "per_op", ("acc", "nll", "ece"))
    vs = load("vlmstate_8b_s[0-9]"); vb = load("vlmstate_8b_both_s[0-9]")
    if vs or vb:
        md += ["", f"## VLM tier reading the shared state: Qwen3-VL-8B LoRA r=64 with the 8x8 pooled Virchow2 tokens injected through a projector, joint PanNuke ({len(vs)} seed tokens only, {len(vb)} seed tokens + own image tokens)", "",
               f"NuCLS test NLL: tokens only {ms([m['test_nll'] for m in vs.values()])}, tokens + pixels {ms([m['test_nll'] for m in vb.values()])}, pixels only (final_vlm, 3 seeds) {ms([m['test_nll'] for m in vlm.values()])}, structured tier {ms([m['test_nll'] for m in fov.values()])}. The tokens-only arm is the diagnostic: the language model reading nothing but the structured tier's state reaches the pixel path, so the accuracy of the VLM tier comes from the pathology state, not from the base model's own vision. Router complementarity does not depend on different visual evidence either: on the same seed pair the oracle over (structured, VLM reading the same state) is 0.856 against 0.859 for (structured, VLM reading pixels), and the learned router reaches 0.800 in both (results/collected/RESULTS_router_state.md). The one operator the tokens-only arm loses is compare_regions (0.59 against 0.80): two boxes on an 8x8 pooled grid are too coarse, which is where the base model's fine image tokens still matter.", ""]
        md += table(vs, "per_op", ("acc", "nll"), extra={"tokens + pixels acc": vb, "pixels only acc (3 seeds)": vlm, "structured acc (3 seeds)": fov})
        md += ["", "PanNuke test:", ""] + table(vs, "per_op_extra", ("acc", "nll"), extra={"tokens + pixels acc": vb, "structured acc (3 seeds)": fov})
    sl = load("final_slide_pan_s[0-9]")
    md += ["", f"## Opsis-S on pan cancer slides, K = 4,096 tiles ({len(sl)} seeds)", "", f"Test NLL {ms([m['test_nll'] for m in sl.values()])}; held out projects (KIRP, STAD, CESC, PAAD) NLL {ms([m.get('test_nll_heldout_project') for m in sl.values()])}. Composite operators were excluded from training and are evaluated held out.", "", "Test split:", ""]
    md += table(sl, "per_op", ("acc", "nll", "ece")) + ["", "Held out projects (KIRP, STAD, CESC, PAAD were never seen in training, so cancer_type is 0 and molecular_subtype near chance by construction; the pan operators are the informative rows):", ""] + table(sl, "per_op_heldout_project", ("acc", "nll", "ece"))
    for pool in ("noisyor", "lse", "topk"):
        ti = load(f"final_tile_{pool}_s[0-9]")
        if not ti: continue
        md += ["", f"## Full bag tile heads, {pool} pooling ({len(ti)} seeds): localised findings", "", "Test split (acc, AUROC, NLL):", ""] + table(ti, "per_op", ("acc", "auroc", "nll")) + ["", "Held out projects:", ""] + table(ti, "per_op_heldout_project", ("acc", "auroc", "nll"))
        for name in ti:
            f = f"{R}/{name}/tile_eval_bcss.json"
            if os.path.exists(f):
                e = json.load(open(f)); md += ["", f"Tile level necrosis against the BCSS masks ({name}, necrotic = necrosis_or_debris >= {e['frac']:.0%} of the tile):", "", "| split | slides | tiles | positive rate | AUROC necrosis head | AP necrosis head | AUROC LVI head | AUROC PNI head | AUROC precursor head |", "|---|---|---|---|---|---|---|---|---|"]
                for r in e["table"]: md.append(f"| {r['split']} | {r['n_slides']} | {r['n_tiles']} | {r['pos_rate']:.3f} | {r.get('auroc_pan_necrosis', float('nan')):.3f} | {r.get('ap_pan_necrosis', float('nan')):.3f} | {r.get('auroc_pan_lvi', float('nan')):.3f} | {r.get('auroc_pan_pni', float('nan')):.3f} | {r.get('auroc_pan_precursor', float('nan')):.3f} |")
    ADD = f"{paths.ROOT}/results/collected/RESULTS_final_addenda.md"; TXT = "\n".join(md) + "\n" + ("\n" + open(ADD).read() if os.path.exists(ADD) else "")
    open(f"{paths.ROOT}/results/collected/RESULTS_final.md", "w").write(TXT); print(TXT)



def ablations():
    """Ablation table for the field decoder of Opsis-S: every runs/abl_*_s<k> against the reference final_fov_s<k> (same seed),
overall and per family accuracy and NLL on the NuCLS test split and PanNuke accuracy; plus the 896 px state runs and the
slide tile budget runs when present.    python scripts/collect/collect.py ablations [--out results/collected/RESULTS_ablations.md]"""
    import argparse, glob, json, os, re
    import numpy as np, pandas as pd
    from opsis.questions import FAMILY
    ap = argparse.ArgumentParser(); ap.add_argument("--out", default=f"{paths.ROOT}/results/collected/RESULTS_ablations.md"); a = ap.parse_args(); R = paths.RUNS
    def load(name):
        f = f"{R}/{name}/metrics_test.json"; return json.load(open(f)) if os.path.exists(f) else None
    def summar(m):
        ops = m["per_op"]; n = sum(v["n"] for v in ops.values()); acc = sum(v["acc"] * v["n"] for v in ops.values()) / n
        fam = {}
        for f in ("cell", "region", "comp"):
            o = [v for k, v in ops.items() if FAMILY.get(k) == f]
            if o: fam[f] = sum(v["acc"] for v in o) / len(o)
        extra = m.get("per_op_extra"); pan = (sum(v["acc"] for v in extra.values()) / len(extra)) if extra else None
        return dict(nll=m["test_nll"], acc=acc, **{f"acc_{k}": v for k, v in fam.items()}, pannuke_acc=pan, cell_super=ops.get("cell_super", {}).get("acc"), cell_area_bin=ops.get("cell_area_bin", {}).get("acc"), compare_regions=ops.get("compare_regions", {}).get("acc"))
    DESC = {"abl_noctx": "no context canvas", "abl_nopool": "no box pooled query tokens", "abl_nodens": "no density auxiliary loss", "abl_nopannuke": "NuCLS only (no PanNuke joint training)", "abl_primitives": "operator encoded by primitive tokens", "abl_small": "readout d=192, 1+1 layers", "abl_large": "readout d=768, 3+3 layers",
            "abl_compholdout": "compositional operators held out of training", "abl_fixed": "fixed multitask heads (no question conditioned attention)", "abl_qps8": "8 questions per state per step", "abl_qps128": "128 questions per state per step", "final_fov896": "896 px state (64 x 64 tokens, FOV at 0.125 mpp)"}
    rows = []
    for d in sorted(glob.glob(f"{R}/abl_*_s[0-9]") + glob.glob(f"{R}/final_fov896_s[0-9]")):
        name = os.path.basename(d); m = load(name)
        if not m: continue
        seed = int(name[-1]); ref = load(f"final_fov_s{seed}"); stem = re.sub(r"_s\d$", "", name)
        s = summar(m); r = summar(ref) if ref else {}
        rows.append(dict(run=name, change=DESC.get(stem, stem), **{k: s[k] for k in s}, **{f"d_{k}": (s[k] - r[k]) if (r.get(k) is not None and s.get(k) is not None) else None for k in ("nll", "acc", "pannuke_acc")}))
    T = pd.DataFrame(rows)
    if len(T):
        ref = summar(load("final_fov_s0")); print("reference final_fov_s0:", {k: (round(v, 3) if isinstance(v, float) else v) for k, v in ref.items()}); print(T.round(3).to_string(index=False))
    sl = []
    for d in sorted(glob.glob(f"{R}/abl_slide_k*_s[0-9]") + glob.glob(f"{R}/final_slide_pan_s0")):
        m = load(os.path.basename(d))
        if m: sl.append(dict(run=os.path.basename(d), k_tiles=m.get("k_tiles"), test_nll=m["test_nll"], **{op: m["per_op"][op]["acc"] for op in ("cancer_type", "pan_grade", "pan_necrosis", "pan_lvi", "pan_pni", "pan_precursor") if op in m["per_op"]}))
    S = pd.DataFrame(sl)
    if len(S): print(S.round(3).to_string(index=False))
    if a.out:
        md = ["# Ablations (generated by scripts/collect/collect.py ablations)", "", "Opsis-S on fields, NuCLS test split, one factor changed from the reference final_fov (joint NuCLS + PanNuke, context, box pooling, density auxiliary, d = 384, 2 + 2 layers, 32 questions per state). d_ columns: difference to the reference run of the same seed.", ""]
        if len(T): md += ["| " + " | ".join(T.columns) + " |", "|" + "---|" * len(T.columns), *("| " + " | ".join("" if (isinstance(x, float) and np.isnan(x)) or x is None else (f"{x:.3f}" if isinstance(x, float) else str(x)) for x in r) + " |" for r in T.itertuples(index=False))]
        if len(S): md += ["", "## Opsis-S slide tile budget", "", "| " + " | ".join(S.columns) + " |", "|" + "---|" * len(S.columns), *("| " + " | ".join(f"{x:.3f}" if isinstance(x, float) else str(x) for x in r) + " |" for r in S.itertuples(index=False))]
        add = f"{paths.ROOT}/results/collected/RESULTS_ablations_addenda.md"; open(a.out, "w").write("\n".join(md) + "\n" + ("\n" + open(add).read() if os.path.exists(add) else "")); print("written", a.out)



def selective():
    """Calibration and selective prediction from the saved test predictions: risk-coverage (accuracy when the least confident
questions are abstained), AURC, ECE, for Opsis-S, Opsis-V and their probability fusion (3 seed pairs), and
the same on PanNuke for seen organs (fold split, final_fov_s<k>) against unseen organs (organ split, final_fov_organ_s0): does
confidence flag the unseen organs and does abstention recover accuracy there.    python scripts/collect/collect.py selective [--out results/collected/RESULTS_selective.md]"""
    import argparse, json, os
    import numpy as np, pandas as pd
    ap = argparse.ArgumentParser(); ap.add_argument("--out", default=f"{paths.ROOT}/results/collected/RESULTS_selective.md"); a = ap.parse_args(); R = paths.RUNS; K = 32
    def load(run, split="test"):
        f = f"{R}/{run}/predictions_{split}.parquet"
        if not os.path.exists(f): return None
        P = pd.read_parquet(f)
        def pad(p): v = np.asarray(p, float); o = np.zeros(K); o[:len(v)] = v[:K]; return o / max(o.sum(), 1e-9)
        P["probs"] = P["probs"].map(pad); return P[["qid", "fov", "op", "family", "answer", "probs"]]
    def curves(P, probs=None):
        p = np.stack(P.probs.to_list()) if probs is None else probs; y = P.answer.to_numpy(); conf = p.max(1); correct = (p.argmax(1) == y)
        order = np.argsort(-conf); c = correct[order]; cov = np.arange(1, len(c) + 1) / len(c); risk = 1 - np.cumsum(c) / np.arange(1, len(c) + 1)
        at = {f"acc@{int(q*100)}": float(1 - risk[int(q * len(c)) - 1]) for q in (1.0, 0.9, 0.8, 0.7, 0.5)}
        bins = np.linspace(0, 1, 11); idx = np.clip(np.digitize(conf, bins) - 1, 0, 9); ece = float(sum(abs(correct[idx == b].mean() - conf[idx == b].mean()) * (idx == b).mean() for b in range(10) if (idx == b).any()))
        return dict(n=len(c), acc=float(correct.mean()), aurc=float(np.trapezoid(risk, cov)), ece=ece, mean_conf=float(conf.mean()), **at)
    rows = []
    for k in range(3):
        S, V = load(f"final_fov_s{k}"), load(f"final_vlm_s{k}")
        if S is None or V is None: continue
        M = S.merge(V[["qid", "probs"]].rename(columns={"probs": "pv"}), on="qid"); ps = np.stack(M.probs.to_list()); pv = np.stack(M.pv.to_list()); g = np.sqrt(ps * pv); g /= g.sum(1, keepdims=True)
        for name, pr in (("structured", ps), ("VLM", pv), ("fusion (geometric mean)", g)): rows.append(dict(set="NuCLS test", seed=k, model=name, **curves(M, pr)))
    T = pd.DataFrame(rows); G = T.groupby(["set", "model"], sort=False).mean(numeric_only=True).drop(columns="seed").reset_index(); print(G.round(3).to_string(index=False))
    # PanNuke: seen organs (fold split test) vs unseen organs (organ split test), Opsis-S
    seen = load("final_fov_s0", "test_extra"); unseen = load("final_fov_organ_s0", "test_extra"); O = []
    if seen is not None and unseen is not None:
        for name, P in (("PanNuke, seen organs (fold split)", seen), ("PanNuke, unseen organs (organ split)", unseen)): O.append(dict(set=name, model="structured", **curves(P)))
        # per FOV mean confidence as an out of distribution score
        cs = seen.assign(conf=seen.probs.map(np.max)).groupby("fov").conf.mean(); cu = unseen.assign(conf=unseen.probs.map(np.max)).groupby("fov").conf.mean()
        from sklearn.metrics import roc_auc_score
        ood = float(roc_auc_score(np.r_[np.zeros(len(cs)), np.ones(len(cu))], -np.r_[cs.to_numpy(), cu.to_numpy()]))
        O.append(dict(set="FOV level: unseen organ detection from mean confidence (AUROC, lower confidence = unseen)", model="structured", auroc=ood, n=len(cs) + len(cu)))
        OD = pd.DataFrame(O); print(OD.round(3).to_string(index=False))
    if a.out:
        md = ["# Calibration and selective prediction (generated by scripts/collect/collect.py selective)", "", "acc@q: accuracy on the q percent most confident questions (the rest abstained). AURC: area under the risk-coverage curve (lower is better). ECE: 10 bin expected calibration error. NuCLS test, mean over 3 seeds (seed pairs for the fusion).", "",
              "| " + " | ".join(G.columns) + " |", "|" + "---|" * len(G.columns), *("| " + " | ".join(f"{x:.3f}" if isinstance(x, float) else str(x) for x in r) + " |" for r in G.itertuples(index=False))]
        if O: md += ["", "## Unseen organs (PanNuke), structured tier", "", "| " + " | ".join(OD.columns) + " |", "|" + "---|" * len(OD.columns), *("| " + " | ".join("" if (isinstance(x, float) and np.isnan(x)) else (f"{x:.3f}" if isinstance(x, float) else str(x)) for x in r) + " |" for r in OD.itertuples(index=False))]
        open(a.out, "w").write("\n".join(md) + "\n"); print("written", a.out)



def organiser():
    """Compare the organiser conditions (results/organiser/<name>_summary.json + .jsonl): accuracy per operator, tool calls, tokens, cost.
    python scripts/collect/collect.py organiser --runs structured_brca30,sol_tools_brca30,sol_vision_brca30,sol_both_brca30 [--price-in 2 --price-out 10] [--out results/collected/RESULTS_organiser.md]"""
    import argparse, json, os
    import numpy as np, pandas as pd
    ap = argparse.ArgumentParser(); ap.add_argument("--runs", required=True); ap.add_argument("--price-in", type=float, default=None, help="USD per million input tokens"); ap.add_argument("--price-out", type=float, default=None); ap.add_argument("--out", default=f"{paths.ROOT}/results/collected/RESULTS_organiser.md"); a = ap.parse_args()
    D = f"{paths.ROOT}/results/organiser"; R = {}
    for n in a.runs.split(","):
        f = f"{D}/{n}.jsonl"
        if os.path.exists(f): R[n] = pd.DataFrame([json.loads(l) for l in open(f)])
    ops = sorted({op for df in R.values() for op in df.operator.unique()}); common = set.intersection(*[set(df.qid) for df in R.values()])
    rows = []
    for op in ops:
        r = {"operator": op, "n": 0}
        for n, df in R.items():
            g = df[(df.operator == op) & df.qid.isin(common)]; r["n"] = len(g); r[n] = f"{g.correct.mean():.3f}" if len(g) else ""
        rows.append(r)
    tot = {"operator": "all (common questions)", "n": len(common)}
    for n, df in R.items():
        g = df[df.qid.isin(common)]; tot[n] = f"{g.correct.mean():.3f}"
    rows.append(tot)
    T = pd.DataFrame(rows); print(T.to_string(index=False))
    cost = []
    for n, df in R.items():
        g = df[df.qid.isin(common)]; pi = sum(u["prompt"] for u in g.usage); po = sum(u["completion"] for u in g.usage)
        c = dict(run=n, questions=len(g), tool_calls_per_q=round(float(g.steps.mean()), 2), input_tokens_per_q=int(pi / max(len(g), 1)), output_tokens_per_q=int(po / max(len(g), 1)), seconds_per_q=round(float(g.seconds.mean()), 1))
        if a.price_in is not None: c["usd_per_q"] = round((pi * a.price_in + po * (a.price_out or 0)) / 1e6 / max(len(g), 1), 4)
        cost.append(c)
    C = pd.DataFrame(cost); print(C.to_string(index=False))
    if a.out:
        md = ["# Organiser arms on the pan TCGA test slides (generated by scripts/collect/collect.py organiser)", "", "Accuracy per operator on the questions all arms answered. structured = the slide readout alone with rule composition (no language model); tools = the language model answering through the typed readouts; vision = the language model looking at a thumbnail and six 256 um tiles; both = vision plus the tools and view_region.", "",
              "| " + " | ".join(T.columns) + " |", "|" + "---|" * len(T.columns), *("| " + " | ".join(str(x) for x in r) + " |" for r in T.itertuples(index=False)), "", "| " + " | ".join(C.columns) + " |", "|" + "---|" * len(C.columns), *("| " + " | ".join(str(x) for x in r) + " |" for r in C.itertuples(index=False))]
        open(a.out, "w").write("\n".join(md) + "\n"); print("written", a.out)



def pan_comparables():
    """Pan TCGA slide level comparison table: the slide decoder of Opsis-S (3 seeds), its full bag tile heads, CLAM-SB (scripts/baselines/57_clam_baseline.py --qset pan, one head per operator, 4,096 tiles per slide, seed 0, test split only), TITAN linear probe
and zero shot, PRISM2 linear probe and zero shot, and the organiser conditions where they exist. Accuracy on the test split
(held out projects in a second table). Runs that do not exist yet are skipped.
    python scripts/collect/collect.py pan_comparables [--out results/collected/RESULTS_pan_comparables.md]"""
    import argparse, glob, json, os
    import numpy as np, pandas as pd
    ap = argparse.ArgumentParser(); ap.add_argument("--out", default=f"{paths.ROOT}/results/collected/RESULTS_pan_comparables.md"); a = ap.parse_args(); R = paths.RUNS
    def load(pat):
        out = []
        for d in sorted(glob.glob(f"{R}/{pat}")):
            f = f"{d}/metrics_test.json"
            if os.path.exists(f): out.append(json.load(open(f)))
        return out
    COLS = [("Opsis-S (3 seeds)", load("final_slide_pan_s[0-9]"), "per_op"), ("ours: tile head lse", load("final_tile_lse_s[0-9]"), "per_op"), ("ours: tile head noisy-OR (3 seeds)", load("final_tile_noisyor_s[0-9]"), "per_op"),
            ("CLAM-SB", load("clam_pan_*_s[0-9]"), "per_op"), ("ABMIL", load("abmil_pan_*_s[0-9]"), "per_op"), ("TITAN probe", load("titan_pan_probe"), "per_op"), ("TITAN zero shot", load("titan_pan_zeroshot"), "per_op"), ("PRISM2 probe", load("prism2_pan_probe"), "per_op"), ("PRISM2 zero shot", load("prism2_pan_zeroshot"), "per_op"),
            ("PRISM2 written report, extracted (unstated = wrong)", load("prism2_report_model"), "per_op", "acc_all_unstated_wrong"), ("PRISM2 report, stated fields only (coverage)", load("prism2_report_model"), "per_op_stated", "acc", "coverage")]
    COLS = [c for c in COLS if c[1]]
    def fmt(vals, nd=3):
        vals = [v for v in vals if v is not None]
        return "" if not vals else (f"{np.mean(vals):.{nd}f}" if len(vals) == 1 else f"{np.mean(vals):.{nd}f} ± {np.std(vals, ddof=1):.{nd}f}")
    def table(key):
        ops = sorted({op for col in COLS for m in col[1] for op in m.get(key, {}) if col[2] == "per_op"}); rows = []
        for op in ops:
            r = {"operator": op}; maj = None
            for col in COLS:
                name, runs = col[0], col[1]; metric = col[3] if len(col) > 3 else "acc"; k2 = col[2] if col[2] != "per_op" and key == "per_op" else (col[2].replace("per_op", key) if col[2] != "per_op" else key)
                if col[2] == "per_op_stated": k2 = "per_op_stated" if key == "per_op" else "per_op_stated_heldout"
                vals = [m[k2][op][metric] for m in runs if op in m.get(k2, {})]; r[name] = fmt(vals)
                if len(col) > 4 and vals: cov = [m["per_op" if key == "per_op" else "per_op_heldout_project"][op][col[4]] for m in runs if op in m.get("per_op" if key == "per_op" else "per_op_heldout_project", {})]; r[name] += f" ({np.mean(cov):.0%})" if cov else ""
                if maj is None and vals and k2 in ("per_op", "per_op_heldout_project"): maj = next(m[k2][op]["majority_acc"] for m in runs if op in m.get(k2, {}))
            r["majority"] = "" if maj is None else f"{maj:.2f}"; rows.append(r)
        T = pd.DataFrame(rows); cols = ["operator", "majority"] + [c[0] for c in COLS]; T = T[cols]
        return ["| " + " | ".join(T.columns) + " |", "|" + "---|" * len(T.columns), *("| " + " | ".join(str(x) for x in r) + " |" for r in T.itertuples(index=False))]
    md = ["# Pan TCGA slide level comparables (generated by scripts/collect/collect.py pan_comparables)", "", "Accuracy on the test split (1,393 slides). Composite operators were never trained by our readouts; the probes train one classifier per operator with labels, and so do CLAM-SB (repository defaults, 4,096 random tiles of the Virchow2 cache per slide, seed 0, test split only) and ABMIL (the gated attention MIL of Ilse et al. 2018, the same network as CLAM-SB without the instance clustering loss, scripts/baselines/57_clam_baseline.py --model abmil, same tiles, three seeds, also scored on the held out projects). TITAN uses its released TCGA slide embeddings (CONCH v1.5 patch features); PRISM2 reads our cached Virchow2 tile embeddings. The report model column scores the free text report PRISM2 writes for the slide (\"Write a report\"), extracted with the same schema as the TCGA reports: a field the report does not state counts as wrong in the first column; the second column scores only the stated fields and gives the coverage in brackets.", ""] + table("per_op")
    md += ["", "## Held out projects (KIRP, STAD, CESC, PAAD; cancer type and molecular subtype are unseen classes by construction)", ""] + table("per_op_heldout_project")
    print("\n".join(md))
    if a.out: open(a.out, "w").write("\n".join(md) + "\n"); print("written", a.out)



def organiser_set():
    """Every comparable on the organiser's own question set (the 189 questions about 30 TCGA-BRCA test slides that every organiser
condition answered), so that the composite rows of the main table compare every model on the same slides and questions. TITAN and
PRISM2 linear probes are refitted with the protocol of scripts/baselines/84_titan_pan.py and 83 (train split, C chosen on val) and scored on these
questions, TITAN and PRISM2 zero shot come from their saved predictions, Opsis-S (final_slide_pan, 3 seeds) from its saved
test predictions, and the organiser conditions from results/organiser. Writes results/collected/RESULTS_organiser_set_comparables.md and
results/organiser/comparables_brca30.json.
    python scripts/collect/collect.py organiser_set"""
    import json, os, pickle
    import numpy as np, pandas as pd
    from sklearn.linear_model import LogisticRegression

    ROOT = paths.ROOT; ORG = f"{ROOT}/results/organiser"; R = paths.RUNS
    ARMS = {"rules": "structured_brca30", "gpt-6-sol tools": "sol_tools_brca30", "gpt-6-sol eyes": "sol_vision_brca30", "gpt-5.5 tools": "gpt55_tools_brca30", "gpt-5.5 eyes": "gpt55_vision_brca30", "gpt-6-astra tools": "gpt6astra_tools_brca30", "gpt-6-astra eyes": "gpt6astra_vision_brca30", "Opus 5.5 tools": "opus55_tools_brca30", "Opus 5.5 eyes": "opus55_vision_brca30"}
    O = {k: pd.DataFrame([json.loads(l) for l in open(f"{ORG}/{v}.jsonl")]) for k, v in ARMS.items()}
    qids = set.intersection(*[set(df.qid) for df in O.values()]); print("common organiser questions", len(qids), flush=True)
    Q = pd.read_parquet(f"{paths.DERIVED}/slide_questions_pan/questions_seed0.parquet")
    S = Q[Q.qid.isin(qids)].copy(); S["label"] = S.apply(lambda r: json.loads(r.candidates)[int(r.answer)], axis=1)
    SYN = ["pan_grade", "pan_lvi", "pan_pni", "pan_necrosis", "pan_precursor", "pan_mitotic", "pan_multifocal"]; COMP = ["high_grade_and_lvi", "necrosis_and_high_mitotic", "grade_from_components", "dcis_with_comedo", "precursor_type"]
    ops = [o for o in SYN + COMP if o in set(S.op)]
    print("slides", S.slide.nunique(), "ops", ops, flush=True)


    def probe(feats, name):
        """refit one logistic regression per operator with the protocol of scripts/baselines/84_titan_pan.py and 83, score the organiser questions"""
        out = {}
        for op in ops:
            g = Q[(Q.op == op) & Q.slide.isin(feats)].copy(); g["label"] = g.apply(lambda r: json.loads(r.candidates)[int(r.answer)], axis=1)
            tr, va, te = g[g.split == "train"], g[g.split == "val"], g[g.qid.isin(qids)]
            cands_all = sorted(g.label.unique()); cidx = {c: i for i, c in enumerate(cands_all)}
            Xtr, Xva = [np.stack([feats[s] for s in x.slide]) for x in (tr, va)]; ytr, yva = [x.label.map(cidx).to_numpy() for x in (tr, va)]
            mu, sd = Xtr.mean(0), Xtr.std(0) + 1e-6; Xtr, Xva = (Xtr - mu) / sd, (Xva - mu) / sd; best = None
            for C in (0.001, 0.01, 0.1, 1.0):
                clf = LogisticRegression(C=C, max_iter=3000).fit(Xtr, ytr); pv = clf.predict_proba(Xva); vl = -np.mean(np.log(np.clip(pv[np.arange(len(yva)), np.searchsorted(clf.classes_, yva)], 1e-9, 1)))
                if best is None or vl < best[0]: best = (vl, C, clf)
            clf = best[2]; Xte = (np.stack([feats[s] for s in te.slide]) - mu) / sd; pred = clf.classes_[clf.predict_proba(Xte).argmax(1)]
            out[op] = dict(acc=float(np.mean(pred == te.label.map(cidx).to_numpy())), n=int(len(te)), C=best[1]); print(f"  {name:12s} {op:26s} n={len(te):3d} acc={out[op]['acc']:.3f} C={best[1]}", flush=True)
        return out


    d = pickle.load(open(f"{paths.MODELS}/TITAN/TCGA_TITAN_features.pkl", "rb")); ET = {str(n): np.asarray(v, np.float32) for n, v in zip(d["filenames"], d["embeddings"])}
    z = np.load(f"{paths.FEATURES}/prism2_pan/embeddings.npz"); EP = dict(zip(map(str, z["slides"]), z["base"]))
    titan_p, prism_p = probe(ET, "TITAN probe"), probe(EP, "PRISM2 probe")


    def zs_acc(P):
        P = P[P.qid.isin(qids)].copy(); out = {}
        for op, g in P.groupby("op"):
            pred = g.probs.map(lambda p: int(np.argmax(json.loads(p) if isinstance(p, str) else p))); out[op] = dict(acc=float((pred == g.answer.astype(int)).mean()), n=int(len(g)))
        return out


    titan_z = zs_acc(pd.read_parquet(f"{R}/titan_pan_zeroshot/predictions_all.parquet")); prism_z = zs_acc(pd.read_parquet(f"{R}/prism2_pan_zeroshot/predictions_test.parquet"))
    seeds = []
    for s in range(3):
        P = pd.read_parquet(f"{R}/final_slide_pan_s{s}/predictions_test.parquet"); seeds.append(zs_acc(P))
    ours = {op: dict(acc=float(np.mean([sd[op]["acc"] for sd in seeds])), sd=float(np.std([sd[op]["acc"] for sd in seeds], ddof=1)), n=seeds[0][op]["n"]) for op in ops if op in seeds[0]}
    maj = {op: float(g.label.value_counts().iloc[0] / len(g)) for op, g in S.groupby("op")}
    org = {k: {op: float(g.correct.mean()) for op, g in df.groupby("operator")} for k, df in O.items()}; org_all = {k: float(df[df.qid.isin(qids)].correct.mean()) for k, df in O.items()}
    maj_all = float(sum(S.groupby("op").label.agg(lambda x: x.value_counts().iloc[0])) / len(S))

    cols = ["operator", "n", "majority", "Opsis-S (3 seeds)", "TITAN probe", "PRISM2 probe", "TITAN zero shot", "PRISM2 zero shot"] + list(ARMS)
    f3 = lambda v: "" if v is None else f"{v:.3f}"
    lines = ["# Every comparable on the organiser question set (generated by scripts/collect/collect.py organiser_set)", "",
             f"The {len(qids)} questions about {S.slide.nunique()} TCGA-BRCA test slides that every organiser arm answered, accuracy per operator. The TITAN and PRISM2 probes are refitted on the train split with C chosen on val (the protocol of scripts/baselines/84_titan_pan.py and 83) and scored on these questions. Zero shot and Opsis-S (the pan slide model, mean over 3 seeds) are read from their saved predictions on the same questions. Rules is Opsis-S with fixed rules and no language model, the composites without a rule counted as wrong. The pan test split numbers of the same models are in results/collected/RESULTS_pan_comparables.md.", "",
             "| " + " | ".join(cols) + " |", "|" + "---|" * len(cols)]
    rows_json = {}
    for op in ops:
        r = [op, str(ours[op]["n"]), f"{maj[op]:.2f}", f"{ours[op]['acc']:.3f} ± {ours[op]['sd']:.3f}", f3(titan_p[op]["acc"]), f3(prism_p[op]["acc"]), f3(titan_z[op]["acc"]) if op in titan_z else "", f3(prism_z[op]["acc"]) if op in prism_z else ""] + [f3(org[k].get(op)) for k in ARMS]
        lines.append("| " + " | ".join(r) + " |"); rows_json[op] = dict(n=ours[op]["n"], majority=maj[op], opsis_s=ours[op]["acc"], opsis_s_sd=ours[op]["sd"], titan_probe=titan_p[op]["acc"], prism2_probe=prism_p[op]["acc"], titan_zs=titan_z.get(op, {}).get("acc"), prism2_zs=prism_z.get(op, {}).get("acc"), **{k.replace(" ", "_").replace("-", "").replace(".", ""): org[k].get(op) for k in ARMS})
    lines.append("| " + " | ".join(["all (common questions)", str(len(qids)), f"{maj_all:.2f}", "", "", "", "", ""] + [f3(org_all[k]) for k in ARMS]) + " |")
    open(f"{ROOT}/results/collected/RESULTS_organiser_set_comparables.md", "w").write("\n".join(lines) + "\n"); json.dump(dict(n=len(qids), per_op=rows_json, all=org_all), open(f"{ORG}/comparables_brca30.json", "w"), indent=1)
    print("\n".join(lines))



def pan_organiser():
    """The Opus 5.5 tools organiser on the whole pan test split (scripts/organiser/81b_pan_organiser.sh), scored per operator next to the comparables of
results/collected/RESULTS_pan_comparables.md, written to results/collected/RESULTS_organiser_pan.md and results/organiser/pan_organiser.json.
cancer_type comes from the aliased rerun (PHASES=ct_alias EXTRA=--alias): the first run saw the TCGA barcode, whose tissue
source site code identifies the cancer type, and cited it in 1,303 of 1,393 reasons; that number is reported as the leak.
The 995 composite questions come from an aliased rerun as well (NAME=opus55_tools_pan_alias PHASES=composites EXTRA=--alias);
the first composite run is reported next to it.
    PYTHONPATH=src OPSIS_DATA=... python scripts/collect/collect.py pan_organiser"""
    import json, glob, re, collections, os, sys
    OUT = f"{paths.ROOT}/results/organiser"; NAME = "opus55_tools_pan"
    PAT = re.compile(r"barcode|tissue source|source site|TSS|TCGA-[A-Z0-9]{2}\b|site code|institution|contribut", re.I)
    def load(pattern): return [json.loads(l) for f in sorted(glob.glob(f"{OUT}/{pattern}")) for l in open(f)]
    first = [r for f in sorted(glob.glob(f"{OUT}/{NAME}_composites_s?.jsonl") + glob.glob(f"{OUT}/{NAME}_synoptic_s?.jsonl") + glob.glob(f"{OUT}/{NAME}_tables_s?.jsonl")) for r in [json.loads(l) for l in open(f)]]
    alias = load(f"{NAME}_ct_alias_s?.jsonl")
    COMPOSITES = ["high_grade_and_lvi", "precursor_type", "necrosis_and_high_mitotic", "grade_from_components", "dcis_with_comedo"]
    # the composite questions were rerun with the alias too (NAME=opus55_tools_pan_alias PHASES=composites EXTRA=--alias); the rerun replaces the first run once it covers every composite question
    alias_comp = load(f"{NAME}_alias_composites_s?.jsonl"); first_comp = [r for r in first if r["operator"] in COMPOSITES]
    USE_ALIAS_COMP = len(alias_comp) > 0 and {r["qid"] for r in alias_comp} >= {r["qid"] for r in first_comp}
    rows = [r for r in first if r["operator"] != "cancer_type" and not (USE_ALIAS_COMP and r["operator"] in COMPOSITES)] + alias + (alias_comp if USE_ALIAS_COMP else [])
    leak = [r for r in first if r["operator"] == "cancer_type"]
    def acc(rs): return sum(r.get("correct", 0) or 0 for r in rs) / len(rs) if rs else float("nan")
    def mentions(rs): return sum(bool(PAT.search(r.get("text") or "")) for r in rs)
    # comparables from the markdown table of scripts/collect/collect.py pan_comparables (test split section)
    comp = {}; hdr = None
    for line in open(f"{paths.ROOT}/results/collected/RESULTS_pan_comparables.md"):
        if line.startswith("## Held out"): break
        c = [x.strip() for x in line.strip().strip("|").split("|")]
        if c[0] == "operator": hdr = {h: i for i, h in enumerate(c)}; continue
        if hdr and len(c) == len(hdr) and not c[0].startswith("-"):
            g = lambda h: c[hdr[h]]
            comp[c[0]] = dict(maj=g("majority"), ours=g("Opsis-S (3 seeds)").split(" ")[0], titan=g("TITAN probe"), titan_zs=g("TITAN zero shot"), prism=g("PRISM2 probe"), prism_zs=g("PRISM2 zero shot"))
    by = collections.defaultdict(list)
    for r in rows: by[r["operator"]].append(r)
    by1 = collections.defaultdict(list)
    for r in first: by1[r["operator"]].append(r)
    ORDER = ["high_grade_and_lvi", "precursor_type", "necrosis_and_high_mitotic", "grade_from_components", "dcis_with_comedo", "pan_grade", "pan_lvi", "pan_pni", "pan_necrosis", "pan_precursor", "pan_mitotic", "pan_multifocal", "pan_infiltrate", "cancer_type", "molecular_subtype", "tumor_purity_bin", "leukocyte_fraction_bin"]
    L = ["# Opus 5.5 tools organiser on the whole pan test split (generated by scripts/collect/collect.py pan_organiser)", "",
         f"Claude Opus 5.5 through the Claude Code CLI with the four Opsis tools (slide_info, ask_slide, tile_evidence, ask_region), every question of the test split (1,393 slides), scripts/organiser/81b_pan_organiser.sh in three phases of four shards. cancer_type and the five composites come from the aliased reruns (--alias), the other rows from the first run. {len(rows):,} questions scored, {sum(r.get('pred') is None for r in rows)} without a parsable answer (counted wrong). The comparables are the full test probes of results/collected/RESULTS_pan_comparables.md: Opsis-S is the slide readout alone (3 seeds; on the composite rows it answers an operator token it never trained, since the composite family was excluded from training; the rule composed answers are in results/organiser/rules_composites.json, scripts/collect/collect.py rules_composites), the TITAN and PRISM2 probes train one classifier per operator on the training split labels, including the composites. Bold: best of the four scored columns on the row.", "",
         "| operator | n | majority | organiser: Opus 5.5 + Opsis tools | Opsis-S | TITAN probe | PRISM2 probe | PRISM2 zero shot |", "|---|---|---|---|---|---|---|---|"]
    js = {}
    for op in ORDER:
        rs = by.get(op, []); c = comp.get(op, {}); a = acc(rs)
        cells = {"org": a, "ours": float(c.get("ours") or "nan"), "titan": float(c.get("titan") or "nan"), "prism": float(c.get("prism") or "nan")}
        best = max(v for v in cells.values() if v == v)
        def f(k): v = cells[k]; return "" if v != v else (f"**{v:.3f}**" if abs(v - best) < 5e-4 else f"{v:.3f}")
        n = f"{len(rs)}" + ("" if op != "cancer_type" or len(alias) >= 1393 else " (aliased rerun in progress)")
        L.append(f"| {op} | {n} | {c.get('maj', '')} | {f('org')} | {f('ours')} | {f('titan')} | {f('prism')} | {c.get('prism_zs', '')} |")
        js[op] = dict(n=len(rs), organiser=round(a, 4), **{k: cells[k] for k in ("ours", "titan", "prism")})
    groups = {"composites": ORDER[:5], "synoptic": ORDER[5:13], "table fields": ORDER[13:]}
    L += ["", "| group | n | organiser | majority |", "|---|---|---|---|"]
    for g, ops in groups.items():
        rs = [r for op in ops for r in by.get(op, [])]
        maj = sum(float(comp[op]["maj"]) * len(by.get(op, [])) for op in ops if op in comp) / max(1, len(rs))
        L.append(f"| {g} | {len(rs)} | {acc(rs):.3f} | {maj:.3f} |"); js[g] = dict(n=len(rs), organiser=round(acc(rs), 4), majority=round(maj, 4))
    cost = sum(r.get("cost_usd") or 0 for r in rows); calls = sum(r.get("steps", 0) for r in rows) / len(rows); tok = sum(r["usage"]["prompt"] for r in rows) / len(rows); out = sum(r["usage"]["completion"] for r in rows) / len(rows); sec = sum(r.get("seconds", 0) for r in rows) / len(rows)
    L += ["", f"Per question: {calls:.2f} tool calls, {tok:,.0f} input tokens, {out:.0f} output tokens, {sec:.1f} s, list price ${cost / len(rows):.3f} (${cost:,.0f} for the split).", "",
          "## The barcode leak on cancer_type", "",
          f"The first cancer_type run showed the organiser the TCGA slide name. Its tissue source site code (TCGA-06 is Henry Ford, a glioblastoma site) identifies the project for most sites, and the model knows the mapping: {mentions(leak)} of {len(leak)} reasons cite the barcode or the contributing site, accuracy {acc(leak):.3f} ({acc([r for r in leak if PAT.search(r.get('text') or '')]):.3f} on the citing episodes, {acc([r for r in leak if not PAT.search(r.get('text') or '')]):.3f} on the rest), against 0.937 for the slide readout it was relaying. slide_info also returned the project (called {sum(any('slide_info' in (t.get('tool') or '') for t in r.get('tools') or []) for r in leak)} times). The rerun (--alias) names the slide slide_<md5 prefix>, resolves the alias inside the MCP server, and hides project and patient in slide_info: {mentions(alias)} of {len(alias)} reasons mention a barcode, accuracy {acc(alias):.3f}. The table above uses the rerun.", "",
          "Barcode mentions in the other operators of the first run, where the site code carries no grade, invasion, purity or subtype label: " + ", ".join(f"{op} {mentions(by1[op])}/{len(by1[op])}" for op in ORDER if op != "cancer_type") + ". The 189 question BRCA organiser set: Opus 5.5 tools 4 of 189, eyes 12 of 189, the three OpenAI models 0 (all BRCA, so no cancer type to infer).", "",
          "## Reading", "",
          "- Composites (never trained, aliased rerun): the organiser composes them from the primitive tools and lands next to the probes that were trained on each composite's labels on the largest row (high grade with LVI, n 479: " + f"{js['high_grade_and_lvi']['organiser']:.3f} against {js['high_grade_and_lvi']['titan']:.3f} and {js['high_grade_and_lvi']['prism']:.3f}" + "), and 6 to 13 points below them on the other four rows (" + ", ".join(f"{op} {js[op]['organiser']:.3f} against {js[op]['titan']:.3f} and {js[op]['prism']:.3f}" for op in COMPOSITES[1:]) + "). The slide readout answering the untrained composite operator token is far below on every composite row (precursor type 0.098); with a fixed rule over its primitives it reaches 0.782 on high grade with LVI and 0.890 on necrosis with high mitotic, and has no rule for the other three (scripts/collect/collect.py rules_composites).",
          "- Composites, first run against the aliased rerun (same " + f"{len(first_comp)} questions): " + ", ".join(f"{op} {acc(by1[op]):.3f} to {acc(by[op]):.3f}" for op in COMPOSITES) + f", all {acc(first_comp):.3f} to {acc(alias_comp):.3f}" + ". " + (lambda a, c, n: f"On precursor type the change is the same on the {len(c)} questions whose first run reason cited the barcode ({acc(c):.3f} to {acc([a[r['qid']] for r in c]):.3f}) and on the other {len(n)} ({acc(n):.3f} to {acc([a[r['qid']] for r in n]):.3f}).")({r["qid"]: r for r in alias_comp}, [r for r in by1["precursor_type"] if PAT.search(r.get("text") or "")], [r for r in by1["precursor_type"] if not PAT.search(r.get("text") or "")]) if USE_ALIAS_COMP else "",
          "- Synoptic: the organiser relays ask_slide (0.722 against 0.703 for one seed of Opsis-S over the eight operators); the small gains come from the few questions where it consults tile_evidence or ask_region in addition.",
          "- Table fields: with the alias, cancer_type is the slide readout's number; molecular subtype, purity and leukocyte fraction are at the readout's level, below the TITAN probe by 2 to 4 points.",
          "- The 189 question subset (results/collected/RESULTS_organiser_opus55.md) overstates the composites: 0.95 and 0.88 on 21 and 8 questions become " + f"{js['high_grade_and_lvi']['organiser']:.2f} and {js['necrosis_and_high_mitotic']['organiser']:.2f}" + " on 479 and 146."]
    open(f"{paths.ROOT}/results/collected/RESULTS_organiser_pan.md", "w").write("\n".join(L) + "\n"); json.dump(js, open(f"{OUT}/pan_organiser.json", "w"), indent=1)
    print("\n".join(L[4:30]))



def eyes():
    """Score the looking runs of scripts/baselines/100_vlm_slide_eyes.py (local VLMs and gpt-6-sol with a thumbnail and six tiles) and the gpt-6-sol looking run of
scripts/organiser/81_organiser_eval.py on the full split composites: accuracy per operator, AUROC of P(yes) on the binary transfer rows (CAMELYON16
metastasis, BCSS necrosis), majority class. Writes results/organiser/eyes_scores.json {model: {qset: {op: {n, acc, auroc}}}}
and results/collected/RESULTS_vlm_eyes.md. Runs are found by name: eyes_<model>_<qset>[_s<i>].jsonl and sol_vision_pan_composites_s<i>.jsonl.
    python scripts/collect/collect.py eyes"""
    import json, glob, os, re, sys, collections
    import numpy as np
    OUT = f"{paths.ROOT}/results/organiser"; MODELS = {"qwen3vl8b": "Qwen3-VL-8B", "pathor1": "Patho-R1-7B", "sol": "gpt-6-sol", "opus55": "Claude Opus 5.5"}
    def rows_of(pattern): return [json.loads(l) for f in sorted(glob.glob(f"{OUT}/{pattern}")) for l in open(f)]
    def auroc(y, s):
        from sklearn.metrics import roc_auc_score
        y = np.asarray(y); s = np.asarray(s, float); ok = np.isfinite(s)
        return float(roc_auc_score(y[ok], s[ok])) if ok.sum() > 1 and 0 < y[ok].sum() < ok.sum() else None
    def score(rows):
        by = collections.defaultdict(list)
        for r in rows: by[r["operator"]].append(r)
        out = {}
        for op, rs in by.items():
            y = [r["answer"] for r in rs]; pred = [r.get("pred") for r in rs]
            maj = max(collections.Counter(y).values()) / len(rs)
            d = dict(n=len(rs), acc=round(sum(p == t for p, t in zip(pred, y)) / len(rs), 4), majority=round(maj, 4), no_answer=sum(p is None for p in pred))
            if all(r.get("probs") and len(r["probs"]) == 2 for r in rs if r.get("probs")) and set(y) <= {0, 1}:
                s = [r["probs"][1] if r.get("probs") else np.nan for r in rs]; au = auroc(y, s)
                if au is not None: d["auroc"] = round(au, 4)
            out[op] = d
        return out
    res = collections.defaultdict(dict)
    for f in glob.glob(f"{OUT}/eyes_*_*.jsonl"):
        m = re.match(r"eyes_(qwen3vl8b|pathor1|sol|opus55)_(pan|brca|camelyon|bcss|nucls)(_s\d+)?\.jsonl", os.path.basename(f))
        if not m: continue
        model, qset = m.group(1), m.group(2)
        if qset in res[model]: continue
        res[model][qset] = score(rows_of(f"eyes_{model}_{qset}*.jsonl"))
    comp = rows_of("sol_vision_pan_composites_s?.jsonl")
    if comp:
        res["sol"].setdefault("pan", {}).update(score(comp))
        allc = score([dict(r, operator="all_composites") for r in comp])["all_composites"]; res["sol"]["pan"]["all_composites"] = allc
    for model in list(res):
        for qset in list(res[model]):
            rs = [r for r in rows_of(f"eyes_{model}_{qset}*.jsonl") if r["operator"] in ("high_grade_and_lvi", "necrosis_and_high_mitotic", "grade_from_components", "precursor_type", "dcis_with_comedo")]
            if qset == "pan" and rs and "all_composites" not in res[model][qset]: res[model][qset]["all_composites"] = score([dict(r, operator="all_composites") for r in rs])["all_composites"]
    json.dump(res, open(f"{OUT}/eyes_scores.json", "w"), indent=1)
    L = ["# Vision language models with their own eyes on the slide level rows (generated by scripts/collect/collect.py eyes)", "",
         "A 1024 px thumbnail and six random 256 um tissue tiles at 0.5 um per pixel per slide (the eyes condition of scripts/organiser/81_organiser_eval.py), no label of the task. Local models score the option letters by the next token logits (scripts/baselines/100_vlm_slide_eyes.py); gpt-6-sol and Claude Opus 5.5 answer in JSON with a confidence, used as the score for AUROC. BCSS: one 128 um tile, necrosis positive when at least half the mask is necrosis or debris. CAMELYON16: the official 129 slide test set.", ""]
    for model, M in res.items():
        L += [f"## {MODELS[model]}", "", "| set | operator | n | majority | accuracy | AUROC | no answer |", "|---|---|---|---|---|---|---|"]
        for qset, ops in M.items():
            for op, d in ops.items(): L.append(f"| {qset} | {op} | {d['n']} | {d['majority']:.3f} | {d['acc']:.3f} | {d.get('auroc', '')} | {d['no_answer']} |")
        L.append("")
    open(f"{paths.ROOT}/results/collected/RESULTS_vlm_eyes.md", "w").write("\n".join(L) + "\n"); print("\n".join(L[3:]))



def rules_composites():
    """Opsis-S with fixed rules on the composite operators of the pan test split: the slide decoder (final_slide_pan_s*, which never
trained the composite family) answers the primitive fields and a rule composes the composite from the probabilities, as in the
rules condition of scripts/organiser/81_organiser_eval.py (--arm structured). Rules exist for high_grade_and_lvi (P(grade 3 or 4) x P(LVI yes)) and
necrosis_and_high_mitotic (P(necrosis yes) x P(mitotic high)); precursor_type, grade_from_components and dcis_with_comedo have
no rule from the pan fields and count as wrong in the "all" row, as in the organiser study. The decoder's own answer to the
untrained operator token (metrics_test.json per_op) is reported beside it for reference. Writes results/organiser/rules_composites.json.
    PYTHONPATH=src OPSIS_DATA=... python scripts/collect/collect.py rules_composites"""
    import json, glob, os, sys, collections
    import numpy as np, pandas as pd
    COMPS = ["high_grade_and_lvi", "precursor_type", "necrosis_and_high_mitotic", "grade_from_components", "dcis_with_comedo"]
    def probs(P, slide, op):
        r = P[(P.fov == slide) & (P.op == op)]
        if r.empty: return None
        r = r.iloc[0]; c = json.loads(r.candidates); return dict(zip(c, r.probs[:len(c)]))
    acc = collections.defaultdict(list); n = {}; untrained = collections.defaultdict(list); later = collections.defaultdict(list); miss = {}
    for d in sorted(glob.glob(f"{paths.RUNS}/final_slide_pan_s[0-9]")):
        P = pd.read_parquet(f"{d}/predictions_test.parquet"); m = json.load(open(f"{d}/metrics_test.json"))["per_op"]
        for op in COMPS:
            Q = P[P.op == op]; n[op] = len(Q); untrained[op].append(m[op]["acc"])
            if op == "high_grade_and_lvi": y = [(lambda g, l: None if g is None or l is None else (g.get("3", 0) + g.get("4", 0)) * l.get("yes", 0))(probs(P, s, "pan_grade"), probs(P, s, "pan_lvi")) for s in Q.fov]
            elif op == "necrosis_and_high_mitotic": y = [(lambda a, b: None if a is None or b is None else a.get("yes", 0) * b.get("high", 0))(probs(P, s, "pan_necrosis"), probs(P, s, "pan_mitotic")) for s in Q.fov]
            else: y = [None] * len(Q)
            pred = [None if v is None else int(v >= 0.5) for v in y]
            acc[op].append(np.mean([p == a for p, a in zip(pred, Q.answer)]) if all(v is not None for v in y) else None)
            # two rules written after the study from the calls the organiser makes. They are not part of
            # the rules condition of the organiser study and are reported apart: the grade with the largest pan_grade probability among the
            # candidates, and P(precursor yes) x P(necrosis yes) >= 0.5
            if op == "grade_from_components":
                pr = [(lambda g, c: None if g is None else int(np.argmax([g.get(k, 0) for k in c])))(probs(P, s, "pan_grade"), json.loads(c)) for s, c in zip(Q.fov, Q.candidates)]
            elif op == "dcis_with_comedo":
                pr = [(lambda a, b: None if a is None or b is None else int(a.get("yes", 0) * b.get("yes", 0) >= 0.5))(probs(P, s, "pan_precursor"), probs(P, s, "pan_necrosis")) for s in Q.fov]
            else: pr = None
            if pr is not None: later[op].append(float(np.mean([p == a for p, a in zip(pr, Q.answer)]))); miss[op] = sum(v is None for v in pr)      # a question whose primitive has no saved prediction counts as wrong
    out = {}
    for op in COMPS:
        a = [v for v in acc[op] if v is not None]
        out[op] = dict(n=n[op], rules=None if not a else round(float(np.mean(a)), 4), rules_sd=None if len(a) < 2 else round(float(np.std(a, ddof=1)), 4), untrained_operator=round(float(np.mean(untrained[op])), 4), seeds=len(acc[op]))
    N = sum(n.values()); out["all"] = dict(n=N, rules_no_rule_wrong=round(sum((out[op]["rules"] or 0) * n[op] for op in COMPS) / N, 4), untrained_operator=round(sum(out[op]["untrained_operator"] * n[op] for op in COMPS) / N, 4))
    for op in later:
        out[op]["rule_written_later"] = round(float(np.mean(later[op])), 4); out[op]["rule_written_later_missing_primitive"] = miss[op]
    W = [op for op in COMPS if out[op]["rules"] is not None or out[op].get("rule_written_later") is not None]
    out["all"]["with_rule_or_later_rule"] = dict(ops=W, n=sum(n[op] for op in W), acc=round(sum((out[op]["rules"] if out[op]["rules"] is not None else out[op]["rule_written_later"]) * n[op] for op in W) / sum(n[op] for op in W), 4))
    # the rules condition with a rule for four of the five composites (the reference condition of the paper): the two
    # first rules and the two written later, precursor type has none and counts as wrong in the total
    for op in COMPS: out[op]["rules_four"] = out[op]["rules"] if out[op]["rules"] is not None else out[op].get("rule_written_later")
    out["all"]["rules_four_no_rule_wrong"] = round(sum((out[op]["rules_four"] or 0) * n[op] for op in COMPS) / N, 4)
    json.dump(out, open(f"{paths.ROOT}/results/organiser/rules_composites.json", "w"), indent=1); print(json.dumps(out, indent=1))



def ways_to_read():
    """Three ways for a frontier model to read a slide, on the organiser question set (the 189 questions about 29 TCGA-BRCA test
slides of scripts/collect/collect.py organiser_set): it reads a written description (the PRISM2 report, or the description Claude Opus 5.5 writes of 6 or 48 tiles, scripts/organiser/106_describe_then_answer.py; gpt-6-sol reads the same cached texts),
it looks (a thumbnail and six prescribed tiles, grey images of the same sizes as the control of that condition, or regions of its own choice: scripts/organiser/81_organiser_eval.py --arm vision, --blank-image, --arm look for Claude,
the Codex run codex_sol_vision for gpt-6-sol), or it asks
typed questions of Opsis-S (scripts/organiser/81_organiser_eval.py --arm tools). Per condition: accuracy, the paired slide bootstrap interval of asking
minus the condition, input tokens per question, the length and cost of the description, views per question, accuracy per
operator. Reads results/organiser/*.jsonl only, the majority class comes from comparables_brca30.json (scripts/collect/collect.py organiser_set).
Writes results/organiser/ways_brca30.json and results/collected/RESULTS_ways_to_read.md.
    python scripts/collect/collect.py ways_to_read"""
    import json, glob, os, re, collections
    import numpy as np

    ROOT = paths.ROOT; ORG = f"{ROOT}/results/organiser"
    os.makedirs(f"{ROOT}/results/collected", exist_ok=True)
    # model -> [(way, condition, file pattern)], the first condition of a model is the one the others are paired against
    RUNS = {
        "Claude Opus 5.5": [("ask", "asks Opsis-S", "opus55_tools_brca30.jsonl"),
                            ("look", "looks at a thumbnail and six tiles", "opus55_vision_brca30.jsonl"),
                            ("look", "looks at views of its own choice", "opus55_look_brca30_s?.jsonl"),
                            ("read", "reads the PRISM2 report", "prism2report_brca30.jsonl"),
                            ("read", "reads its own description of 6 tiles", "opus55_describe6_brca30_s?.jsonl"),
                            ("read", "reads its own description of 48 tiles", "opus55_describe48_brca30_s?.jsonl")],
        "gpt-6-sol": [("ask", "asks Opsis-S", "sol_tools_brca30.jsonl"), ("look", "looks at a thumbnail and six tiles", "sol_vision_brca30.jsonl"),
                      ("look", "looks at grey images in their place", "sol_vision_blank_brca30.jsonl"),          # scripts/organiser/81_organiser_eval.py --arm vision --blank-image: the same prompt, every image replaced by a grey one of its size
                      ("look", "looks at views of its own choice", "codex_sol_vision_brca30.jsonl"),
                      ("read", "reads the PRISM2 report", "sol_prism2report_brca30.jsonl"),
                      ("read", "reads the description of 6 tiles by Claude Opus 5.5", "sol_describe6_brca30.jsonl"),
                      ("read", "reads the description of 48 tiles by Claude Opus 5.5", "sol_describe48_brca30.jsonl")],   # scripts/organiser/106_describe_then_answer.py --answer-backend api: the cached text, answered by gpt-6-sol
        "gpt-5.5": [("ask", "asks Opsis-S", "gpt55_tools_brca30.jsonl"), ("look", "looks at a thumbnail and six tiles", "gpt55_vision_brca30.jsonl")],
        "gpt-6-astra": [("ask", "asks Opsis-S", "gpt6astra_tools_brca30.jsonl"), ("look", "looks at a thumbnail and six tiles", "gpt6astra_vision_brca30.jsonl")],
    }
    VIEW = re.compile(r"'tool': '[^']*view_region'")   # one call = one region chosen by the model (the thumbnail is not counted)


    def load(pattern):
        rows = {}
        for f in sorted(glob.glob(f"{ORG}/{pattern}")):
            for l in open(f):
                r = json.loads(l); rows[r["qid"]] = r          # a resumed shard may repeat a question, the last answer counts
        return rows


    def boot(a, b, slides, n=10000, seed=0):
        """paired bootstrap over slides of mean(a) - mean(b), a and b are correctness vectors over the same questions"""
        rng = np.random.default_rng(seed); u = sorted(set(slides)); idx = {s: np.flatnonzero(np.asarray(slides) == s) for s in u}
        d = []
        for _ in range(n):
            pick = np.concatenate([idx[u[i]] for i in rng.integers(0, len(u), len(u))]); d.append(a[pick].mean() - b[pick].mean())
        return float(np.percentile(d, 2.5)), float(np.percentile(d, 97.5))


    comp = json.load(open(f"{ORG}/comparables_brca30.json")); N = comp["n"]
    maj = sum(v["majority"] * v["n"] for v in comp["per_op"].values()) / sum(v["n"] for v in comp["per_op"].values())
    res = dict(n=N, majority=round(maj, 4), models={})
    L = ["# Three ways for a frontier model to read a slide (generated by scripts/collect/collect.py ways_to_read)", "",
         f"The {N} questions about TCGA-BRCA test slides of the organiser question set, majority class {maj:.3f}. A model reads a written description of the slide and answers from the text alone, looks at pixels, or asks typed questions of Opsis-S. The interval is the paired bootstrap over slides (10,000 resamples) of asking minus the condition, in points. Input tokens are the mean prompt tokens per question as reported by each backend, description tokens are spent once per slide.", ""]
    for model, conds in RUNS.items():
        ref = None; M = []
        for way, name, pattern in conds:
            rows = load(pattern)
            if not rows: print("missing", model, name, pattern); continue
            if ref is None: ref = rows
            q = sorted(set(rows) & set(ref)); slides = [rows[i]["slide"] for i in q]
            c = np.array([bool(rows[i]["correct"]) for i in q], float); cr = np.array([bool(ref[i]["correct"]) for i in q], float)
            d = dict(way=way, condition=name, n=len(rows), complete=len(rows) == N, acc=round(float(np.mean([bool(r["correct"]) for r in rows.values()])), 6),
                     no_answer=sum(r.get("pred") is None for r in rows.values()), input_tokens=round(float(np.mean([r["usage"]["prompt"] for r in rows.values() if r.get("usage")])), 0))
            if rows is not ref:
                lo, hi = boot(cr, c, slides); d.update(ask_minus=round(100 * float(cr.mean() - c.mean()), 1), ci=[round(100 * lo, 1), round(100 * hi, 1)], n_paired=len(q))
            views = [len(VIEW.findall(str(r.get("tools", "")))) for r in rows.values()]
            if way == "look" and sum(views): d["views"] = round(float(np.mean(views)), 1)
            if any("desc_words" in r for r in rows.values()):
                per_slide = {r["slide"]: r for r in rows.values()}                 # the description is written once per slide
                d["desc_words"] = round(float(np.mean([r["desc_words"] for r in per_slide.values()])), 0)
                d["desc_tokens"] = round(float(np.mean([r["desc_usage"]["prompt"] + r["desc_usage"]["completion"] for r in per_slide.values()])), 0)
            by = collections.defaultdict(list)
            for r in rows.values(): by[r["operator"]].append(bool(r["correct"]))
            d["per_op"] = {op: round(float(np.mean(v)), 6) for op, v in sorted(by.items())}
            M.append(d)
        res["models"][model] = M
        L += [f"## {model}", "", "| way | condition | n | accuracy | asking minus this, points | input tokens per question | views per question | description words | description tokens per slide |", "|---|---|---|---|---|---|---|---|---|"]
        for d in M:
            ci = f"{d['ask_minus']:+.1f} [{d['ci'][0]:.1f}, {d['ci'][1]:.1f}]" if "ci" in d else ""
            L.append(f"| {d['way']} | {d['condition']} | {d['n']} | {d['acc']:.3f} | {ci} | {d['input_tokens']:.0f} | {d.get('views', '')} | {d.get('desc_words', '')} | {d.get('desc_tokens', '')} |")
        L.append("")
    ops = sorted({op for M in res["models"].values() for d in M for op in d["per_op"]})
    M = res["models"]["Claude Opus 5.5"]
    L += ["## Claude Opus 5.5, accuracy per operator", "", "| operator | n | majority | " + " | ".join(d["condition"] for d in M) + " |", "|---|---|---|" + "---|" * len(M)]
    for op in ops:
        L.append(f"| {op} | {comp['per_op'][op]['n']} | {comp['per_op'][op]['majority']:.2f} | " + " | ".join(f"{d['per_op'].get(op, float('nan')):.2f}" for d in M) + " |")
    # ---- the whole test split: the 12 operators of scripts/organiser/106_describe_then_answer.py on every test slide (no pan_infiltrate), paired on the question ids ----
    PAN = [("ask", "Claude Opus 5.5 asks Opsis-S", ["opus55_tools_pan_alias_composites_s?.jsonl", "opus55_tools_pan_synoptic_s?.jsonl"]),
           ("ask", "gpt-6-sol asks Opsis-S", ["sol_tools_pan_alias_composites_s?.jsonl", "sol_tools_pan_alias_synoptic_s?.jsonl"]),
           ("read", "gpt-6-sol reads the PRISM2 report", ["sol_prism2report_pan_s?.jsonl"])]
    COMPOSITES = ["high_grade_and_lvi", "necrosis_and_high_mitotic", "grade_from_components", "dcis_with_comedo", "precursor_type"]
    P = {name: {k: v for pat in pats for k, v in load(pat).items()} for _, name, pats in PAN}; P = {k: v for k, v in P.items() if v}
    if "gpt-6-sol reads the PRISM2 report" in P:
        base = P["gpt-6-sol reads the PRISM2 report"]; pan = dict(n=len(base), n_slides=len({r["slide"] for r in base.values()}), conditions={}, pairs=[])
        # the majority class of an operator is its most frequent answer among these test questions, a family's is the n weighted mean over its operators
        gold = collections.defaultdict(list)
        for r in base.values(): gold[r["operator"]].append(str(r["answer"]))
        pan["per_op"] = {o: dict(n=len(g), majority=round(collections.Counter(g).most_common(1)[0][1] / len(g), 6)) for o, g in sorted(gold.items())}
        fam = lambda ops: round(sum(pan["per_op"][o]["majority"] * pan["per_op"][o]["n"] for o in ops) / max(sum(pan["per_op"][o]["n"] for o in ops), 1), 6)
        pan["majority"] = dict(all=fam(list(gold)), composites=fam([o for o in gold if o in COMPOSITES]), synoptic=fam([o for o in gold if o not in COMPOSITES]))
        L += ["", "## The whole test split", "", f"The same 12 operators on every test slide: {len(base)} questions about {pan['n_slides']} slides, majority class {pan['majority']['all']:.3f} (composites {pan['majority']['composites']:.3f}, synoptic {pan['majority']['synoptic']:.3f}). "
              "The interval is the paired bootstrap over slides (10,000 resamples) of the first condition minus the second, in points.", "",
              "| condition | n | accuracy | composites | synoptic | input tokens per question |", "|---|---|---|---|---|---|"]
        for name, R in P.items():
            q = sorted(set(R) & set(base)); acc = lambda ks: float(np.mean([bool(R[k]["correct"]) for k in ks])) if ks else float("nan")
            co = [k for k in q if R[k]["operator"] in COMPOSITES]; sy = [k for k in q if R[k]["operator"] not in COMPOSITES]
            by = collections.defaultdict(list)
            for k in q: by[R[k]["operator"]].append(bool(R[k]["correct"]))
            tok = round(float(np.mean([R[k]["usage"]["prompt"] for k in q if R[k].get("usage")])), 0)
            pan["conditions"][name] = dict(n=len(q), complete=len(q) == len(base), acc=round(acc(q), 6), composites=round(acc(co), 6), synoptic=round(acc(sy), 6), input_tokens=tok, per_op={o: round(float(np.mean(v)), 6) for o, v in sorted(by.items())})
            L.append(f"| {name} | {len(q)} | {acc(q):.3f} | {acc(co):.3f} | {acc(sy):.3f} | {tok:.0f} |")
        L += ["", "| first minus second | n | all | composites | synoptic | same answer |", "|---|---|---|---|---|---|"]
        def diff(A, B, keep):
            q = sorted(k for k in set(P[A]) & set(P[B]) & set(base) if keep(P[A][k]["operator"]))      # the 12 operators only: both organiser runs also asked pan_infiltrate
            if not q: return dict(n=0), ""                                                    # a run still in progress has no question of this family yet
            x = np.array([bool(P[A][k]["correct"]) for k in q], float); y = np.array([bool(P[B][k]["correct"]) for k in q], float)
            lo, hi = boot(x, y, [P[A][k]["slide"] for k in q]); d = dict(n=len(q), diff=round(100 * float(x.mean() - y.mean()), 1), ci=[round(100 * lo, 1), round(100 * hi, 1)])
            return d, f"{d['diff']:+.1f} [{d['ci'][0]:.1f}, {d['ci'][1]:.1f}]"
        for A, B in [("Claude Opus 5.5 asks Opsis-S", "gpt-6-sol reads the PRISM2 report"), ("gpt-6-sol asks Opsis-S", "gpt-6-sol reads the PRISM2 report"), ("Claude Opus 5.5 asks Opsis-S", "gpt-6-sol asks Opsis-S")]:
            if A not in P or B not in P: continue
            cells = []; row = dict(first=A, second=B)
            for lab, keep in [("all", lambda o: True), ("composites", lambda o: o in COMPOSITES), ("synoptic", lambda o: o not in COMPOSITES)]:
                row[lab], c = diff(A, B, keep); cells.append(c)
            q = sorted(set(P[A]) & set(P[B]) & set(base)); row["same_answer"] = round(float(np.mean([str(P[A][k].get("pred")) == str(P[B][k].get("pred")) for k in q])), 6)
            if A.split(" asks")[0] == B.split(" reads")[0]: row["per_op"] = {o: diff(A, B, lambda x, o=o: x == o)[0] for o in sorted(gold)}      # the same model asking and reading, per operator
            pan["pairs"].append(row); L.append(f"| {A} minus {B} | {row['all']['n']} | " + " | ".join(cells) + f" | {row['same_answer']:.3f} |")
        same = next((r for r in pan["pairs"] if "per_op" in r), None)
        if same:
            names = list(pan["conditions"]); L += ["", f"| operator | n | majority | " + " | ".join(names) + f" | {same['first']} minus {same['second']} |", "|---|---|---|" + "---|" * (len(names) + 1)]
            for o, v in pan["per_op"].items():
                d = same["per_op"][o]; L.append(f"| {o} | {v['n']} | {v['majority']:.3f} | " + " | ".join(f"{pan['conditions'][c]['per_op'].get(o, float('nan')):.3f}" for c in names) + f" | {d['diff']:+.1f} [{d['ci'][0]:.1f}, {d['ci'][1]:.1f}] |")
        res["pan"] = pan
    json.dump(res, open(f"{ORG}/ways_brca30.json", "w"), indent=1)
    open(f"{ROOT}/results/collected/RESULTS_ways_to_read.md", "w").write("\n".join(L) + "\n"); print("\n".join(L[2:]))


COMMANDS = {"baselines": baselines, "router": router, "final": final, "ablations": ablations, "selective": selective, "organiser": organiser, "pan_comparables": pan_comparables, "organiser_set": organiser_set, "pan_organiser": pan_organiser, "eyes": eyes, "rules_composites": rules_composites, "ways_to_read": ways_to_read}

if __name__ == "__main__":
    if len(sys.argv) < 2 or sys.argv[1] not in COMMANDS:
        sys.exit(__doc__)
    cmd = sys.argv.pop(1); sys.argv[0] = f"collect.py {cmd}"
    COMMANDS[cmd]()
